 const cornerLabel=document.createElement('label');cornerLabel.textContent='F8 button position: ';const cornerSelect=document.createElement('select');cornerSelect.setAttribute('aria-label','F8 button position');for(const [value,label]of [['top-left','Top left'],['top-right','Top right'],['bottom-left','Bottom left'],['bottom-right','Bottom right']]){const option=document.createElement('option');option.value=value;option.textContent=label;cornerSelect.append(option);}cornerSelect.value=options.triggerCorner;cornerSelect.onchange=()=>{options.triggerCorner=cornerSelect.value;localStorage.setItem('pd2-options',JSON.stringify(options));positionTrigger();};cornerLabel.append(cornerSelect);settings.append(cornerLabel);
 for(const [key,label] of [['barSetting','Show side bar'],['popupSetting','Floor popups'],['timerSetting','Green timer']]){const b=document.createElement('button');b.textContent=label+': '+(options[key]?'On':'Off');b.onclick=()=>{options[key]=!options[key];localStorage.setItem('pd2-options',JSON.stringify(options));if(polyMod.polyDipEnabled){polyMod.barDiv.style.opacity=options.barSetting?'1':'0';polyMod.greenTimer.style.opacity=options.timerSetting?'.7':'0';}renderSettings();};settings.append(b);}
